import type { ReactNode } from "react";

import type { BubbleBackgroundMotion } from "@/registry/radix-nova/bubble-background";

export type BubbleBackgroundTheme = {
  hue?: number;
  hueSpread?: number;
  saturation?: number;
  lightness?: number;
  opacity?: number;
  overlay?: number;
};

export type ConfigurableBubbleBackgroundProps = {
  className?: string;
  children?: ReactNode;
  bubbleCount?: number;
  blur?: number;
  motion?: BubbleBackgroundMotion;
  initialSize?: { width: number; height: number };
  reducedMotion?: boolean;
};

export type ResolvedBubbleBackgroundTheme = {
  hue: number;
  hueSpread: number;
  saturation: number;
  lightness: number;
  opacity: number;
  overlay: number;
};

export type BubbleBackgroundSceneTheme = BubbleBackgroundTheme & {
  key?: string;
  accentHue?: number;
};

export type BubbleBackgroundThemeDefaults = {
  key: string;
  hue: number;
  accentHue?: number;
  hueSpread: number;
  saturation: number;
  lightness: number;
  opacity: number;
  overlay: number;
};

export type ResolvedBubbleBackgroundSceneTheme = ResolvedBubbleBackgroundTheme & {
  key: string;
  accentHue: number;
};

export type BubbleBackgroundSceneConfig = {
  key: string;
  vignette: string | null;
  bubbleSize: [number, number];
  initialXRange: [number, number];
  initialYRange: [number, number];
  saturationVariance: number;
  lightnessVariance: number;
  opacityVariance: number;
  overlayTopAlphaMultiplier: number;
  backdropStyle: "spread" | "accent";
};

export function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

export function normalizeHue(hue: number) {
  return ((hue % 360) + 360) % 360;
}

export function createRng(seed: number) {
  let state = seed || 1;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let next = Math.imul(state ^ (state >>> 15), 1 | state);
    next ^= next + Math.imul(next ^ (next >>> 7), 61 | next);
    return ((next ^ (next >>> 14)) >>> 0) / 4294967296;
  };
}

export function hashBubbleBackgroundKey(value: string) {
  let hash = 2166136261;

  for (let index = 0; index < value.length; index++) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }

  return hash >>> 0;
}

export function pickBetween(rng: () => number, min: number, max: number) {
  return min + (max - min) * rng();
}

export function resolveBubbleBackgroundTheme(
  theme: BubbleBackgroundSceneTheme | undefined,
  defaults: BubbleBackgroundThemeDefaults,
): ResolvedBubbleBackgroundSceneTheme {
  const hue = normalizeHue(theme?.hue ?? defaults.hue);
  const hueSpread = clamp(theme?.hueSpread ?? defaults.hueSpread, 0, 180);

  return {
    key: theme?.key ?? defaults.key,
    hue,
    accentHue: normalizeHue(
      theme?.accentHue ?? defaults.accentHue ?? hue + Math.max(hueSpread, 18),
    ),
    hueSpread,
    saturation: clamp(theme?.saturation ?? defaults.saturation, 0, 100),
    lightness: clamp(theme?.lightness ?? defaults.lightness, 0, 100),
    opacity: clamp(theme?.opacity ?? defaults.opacity, 0, 1),
    overlay: clamp(theme?.overlay ?? defaults.overlay, 0, 1),
  };
}

export function getBubbleBackgroundThemeSignature(theme: ResolvedBubbleBackgroundSceneTheme) {
  return [
    theme.key,
    theme.hue,
    theme.accentHue,
    theme.hueSpread,
    theme.saturation,
    theme.lightness,
    theme.opacity,
    theme.overlay,
  ].join(":");
}

export function cloneBubbleBackgroundMotion(
  motion: BubbleBackgroundMotion,
): BubbleBackgroundMotion {
  return {
    driftMinMs: motion.driftMinMs,
    driftMaxMs: motion.driftMaxMs,
    waypoints: motion.waypoints,
    overshoot: motion.overshoot,
  };
}

export function cloneBubbleBackgroundInitialSize(initialSize: { width: number; height: number }) {
  return { width: initialSize.width, height: initialSize.height };
}

export function getBubbleBackgroundSceneSignature({
  theme,
  scene,
  bubbleCount,
  blur,
  motion,
  initialSize,
}: {
  theme: ResolvedBubbleBackgroundSceneTheme;
  scene: BubbleBackgroundSceneConfig;
  bubbleCount: number;
  blur: number;
  motion: BubbleBackgroundMotion;
  initialSize: { width: number; height: number };
}) {
  return [
    getBubbleBackgroundThemeSignature(theme),
    scene.key,
    bubbleCount,
    blur,
    motion.driftMinMs,
    motion.driftMaxMs,
    motion.waypoints,
    motion.overshoot,
    initialSize.width,
    initialSize.height,
    scene.bubbleSize[0],
    scene.bubbleSize[1],
    scene.initialXRange[0],
    scene.initialXRange[1],
    scene.initialYRange[0],
    scene.initialYRange[1],
    scene.saturationVariance,
    scene.lightnessVariance,
    scene.opacityVariance,
    scene.overlayTopAlphaMultiplier,
    scene.backdropStyle,
  ].join(":");
}

function buildBubbleBackdrop(
  theme: ResolvedBubbleBackgroundSceneTheme,
  backdropStyle: BubbleBackgroundSceneConfig["backdropStyle"],
) {
  if (backdropStyle === "accent") {
    const primarySaturation = clamp(theme.saturation - 24, 10, 80);
    const accentSaturation = clamp(theme.saturation - 32, 8, 72);

    return [
      `radial-gradient(circle at 18% 14%, hsl(${theme.hue} ${primarySaturation.toFixed(0)}% 97% / 0.9), transparent 42%)`,
      `radial-gradient(circle at 82% 78%, hsl(${theme.accentHue} ${accentSaturation.toFixed(0)}% 93% / 0.72), transparent 46%)`,
      `linear-gradient(180deg, hsl(${theme.hue} ${clamp(primarySaturation - 10, 5, 72).toFixed(0)}% 98%), hsl(${theme.accentHue} ${clamp(accentSaturation - 8, 5, 64).toFixed(0)}% 94%))`,
    ].join(",");
  }

  const saturation = clamp(theme.saturation - 24, 10, 80);

  return [
    `radial-gradient(circle at 18% 14%, hsl(${theme.hue} ${clamp(saturation - theme.hueSpread * 0.4, 0, 100).toFixed(0)}% 97% / 0.9), transparent 42%)`,
    `radial-gradient(circle at 82% 78%, hsl(${theme.accentHue} ${clamp(saturation - theme.hueSpread * 0.8, 0, 100).toFixed(0)}% 93% / 0.72), transparent 46%)`,
    `linear-gradient(180deg, hsl(${theme.hue} ${clamp(saturation - 10, 5, 80)}% 98%), hsl(${theme.accentHue} ${clamp(saturation - 15, 5, 72)}% 94%))`,
  ].join(",");
}

function buildBubbleOverlay(
  theme: ResolvedBubbleBackgroundSceneTheme,
  overlayTopAlphaMultiplier: number,
) {
  if (theme.overlay <= 0) {
    return null;
  }

  return `linear-gradient(180deg, hsl(${theme.hue} 26% 99% / ${(theme.overlay * overlayTopAlphaMultiplier).toFixed(2)}), hsl(${theme.accentHue} 18% 98% / ${theme.overlay.toFixed(2)}))`;
}

function buildBubbleLayerBubbles({
  theme,
  scene,
  layerId,
  seed,
  bubbleCount,
}: {
  theme: ResolvedBubbleBackgroundSceneTheme;
  scene: BubbleBackgroundSceneConfig;
  layerId: string;
  seed: number;
  bubbleCount: number;
}) {
  const rng = createRng(seed);

  return Array.from({ length: bubbleCount }, (_, index) => {
    const hue = normalizeHue(theme.hue + pickBetween(rng, -theme.hueSpread, theme.hueSpread));
    const saturation = clamp(
      theme.saturation + pickBetween(rng, -scene.saturationVariance, scene.saturationVariance),
      0,
      100,
    );
    const lightness = clamp(
      theme.lightness + pickBetween(rng, -scene.lightnessVariance, scene.lightnessVariance),
      0,
      100,
    );
    const opacity = clamp(
      theme.opacity + pickBetween(rng, -scene.opacityVariance, scene.opacityVariance),
      0.05,
      1,
    );
    const width = pickBetween(rng, scene.bubbleSize[0], scene.bubbleSize[1]);

    return {
      id: `${layerId}-${index}`,
      initialX: pickBetween(rng, scene.initialXRange[0], scene.initialXRange[1]),
      initialY: pickBetween(rng, scene.initialYRange[0], scene.initialYRange[1]),
      width,
      height: width * pickBetween(rng, 0.82, 1.22),
      highlightColor: `hsl(${hue.toFixed(0)} ${clamp(saturation + 8, 0, 100).toFixed(0)}% ${clamp(lightness + 18, 0, 100).toFixed(0)}%)`,
      color: `hsl(${hue.toFixed(0)} ${saturation.toFixed(0)}% ${lightness.toFixed(0)}%)`,
      opacity,
    };
  });
}

export function createBubbleBackgroundLayer({
  layerId,
  seed,
  theme,
  scene,
  bubbleCount,
  blur,
  motion,
  initialSize,
}: {
  layerId: string;
  seed: number;
  theme: ResolvedBubbleBackgroundSceneTheme;
  scene: BubbleBackgroundSceneConfig;
  bubbleCount: number;
  blur: number;
  motion: BubbleBackgroundMotion;
  initialSize: { width: number; height: number };
}) {
  return {
    id: layerId,
    bubbles: buildBubbleLayerBubbles({ theme, scene, layerId, seed, bubbleCount }),
    backdrop: buildBubbleBackdrop(theme, scene.backdropStyle),
    overlay: buildBubbleOverlay(theme, scene.overlayTopAlphaMultiplier),
    vignette: scene.vignette,
    blur,
    motion,
    initialSize,
  };
}

"use client";

import { useEffect, useEffectEvent, useId, useMemo, useRef, useState } from "react";

import {
  BubbleBackground,
  type BubbleBackgroundLayer,
  type BubbleBackgroundMotion,
} from "@/registry/radix-nova/bubble-background";
import {
  cloneBubbleBackgroundInitialSize,
  cloneBubbleBackgroundMotion,
  createBubbleBackgroundLayer,
  getBubbleBackgroundSceneSignature,
  hashBubbleBackgroundKey,
  resolveBubbleBackgroundTheme,
  type BubbleBackgroundSceneConfig,
  type BubbleBackgroundSceneTheme,
  type BubbleBackgroundThemeDefaults,
  type ConfigurableBubbleBackgroundProps,
  type ResolvedBubbleBackgroundSceneTheme,
} from "@/registry/radix-nova/bubble-background-helpers";
import { usePrefersReducedMotion } from "@/registry/radix-nova/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

type ConfigurableBubbleBackgroundSceneProps = ConfigurableBubbleBackgroundProps & {
  theme?: BubbleBackgroundSceneTheme;
  themeDefaults: BubbleBackgroundThemeDefaults;
  scene: BubbleBackgroundSceneConfig;
  bubbleCount: number;
  blur: number;
  motion: BubbleBackgroundMotion;
  initialSize: { width: number; height: number };
  seed?: number;
  crossfade?: boolean;
};

type LayerState = {
  layer: BubbleBackgroundLayer;
  mode: "steady" | "enter" | "exit";
};

const EXIT_MS = 900;

const ENTER_CLASS_NAME = "[animation:c-ui-bubble-layer-enter_0.9s_ease-out_both]";
const EXIT_CLASS_NAME = "[animation:c-ui-bubble-layer-exit_0.8s_ease-out_both]";

const BUBBLE_LAYER_KEYFRAMES = `
@keyframes c-ui-bubble-layer-enter {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes c-ui-bubble-layer-exit {
  to {
    opacity: 0;
  }
}
`;

function createTransitionLayer({
  bubbleCount,
  blur,
  initialSize,
  mode = "enter",
  motion,
  scene,
  theme,
  layerId,
  seed,
}: {
  theme: ResolvedBubbleBackgroundSceneTheme;
  scene: BubbleBackgroundSceneConfig;
  bubbleCount: number;
  blur: number;
  mode?: LayerState["mode"];
  motion: BubbleBackgroundMotion;
  initialSize: { width: number; height: number };
  layerId: string;
  seed: number;
}): LayerState {
  return {
    layer: createBubbleBackgroundLayer({
      layerId,
      seed,
      theme,
      scene,
      bubbleCount,
      blur,
      motion,
      initialSize,
    }),
    mode,
  };
}

export function ConfigurableBubbleBackground({
  theme,
  themeDefaults,
  scene,
  className,
  children,
  bubbleCount,
  blur,
  motion,
  initialSize,
  reducedMotion: reducedMotionProp,
  seed,
  crossfade = false,
}: ConfigurableBubbleBackgroundSceneProps) {
  const preferredReducedMotion = usePrefersReducedMotion();
  const reducedMotion =
    reducedMotionProp === undefined ? preferredReducedMotion : reducedMotionProp;

  const { driftMinMs, driftMaxMs, overshoot, waypoints } = motion;
  const { width: initialWidth, height: initialHeight } = initialSize;

  const resolvedTheme = useMemo(
    () => resolveBubbleBackgroundTheme(theme, themeDefaults),
    [theme, themeDefaults],
  );
  const resolvedMotion = useMemo(
    () => cloneBubbleBackgroundMotion({ driftMinMs, driftMaxMs, overshoot, waypoints }),
    [driftMaxMs, driftMinMs, overshoot, waypoints],
  );
  const resolvedInitialSize = useMemo(
    () => cloneBubbleBackgroundInitialSize({ width: initialWidth, height: initialHeight }),
    [initialHeight, initialWidth],
  );
  const signature = useMemo(
    () =>
      getBubbleBackgroundSceneSignature({
        theme: resolvedTheme,
        scene,
        bubbleCount,
        blur,
        motion: resolvedMotion,
        initialSize: resolvedInitialSize,
      }),
    [blur, bubbleCount, resolvedInitialSize, resolvedMotion, resolvedTheme, scene],
  );
  const instanceId = useId();
  const initialLayerId = `${scene.key}-${instanceId}-0`;
  const baseSeed = useMemo(
    () => seed ?? hashBubbleBackgroundKey(`${signature}:${instanceId}`),
    [instanceId, seed, signature],
  );
  const transitionSignature = `${signature}:${baseSeed}`;
  const createNextTransitionLayer = useEffectEvent((transitionIndex: number) =>
    createTransitionLayer({
      theme: resolvedTheme,
      scene,
      bubbleCount,
      blur,
      motion: resolvedMotion,
      initialSize: resolvedInitialSize,
      layerId: `${scene.key}-${instanceId}-${transitionIndex}`,
      seed: hashBubbleBackgroundKey(`${transitionSignature}:${instanceId}:${transitionIndex}`),
    }),
  );

  const layers = useMemo<BubbleBackgroundLayer[]>(() => {
    if (crossfade) {
      return [];
    }

    return [
      createBubbleBackgroundLayer({
        layerId: initialLayerId,
        seed: baseSeed,
        theme: resolvedTheme,
        scene,
        bubbleCount,
        blur,
        motion: resolvedMotion,
        initialSize: resolvedInitialSize,
      }),
    ];
  }, [
    blur,
    bubbleCount,
    crossfade,
    initialLayerId,
    baseSeed,
    resolvedInitialSize,
    resolvedMotion,
    resolvedTheme,
    scene,
  ]);

  const transitionLayerIndexRef = useRef(1);
  const [transitionLayers, setTransitionLayers] = useState<LayerState[]>(() => {
    if (!crossfade) {
      return [];
    }

    return [
      createTransitionLayer({
        theme: resolvedTheme,
        scene,
        bubbleCount,
        blur,
        mode: "steady",
        motion: resolvedMotion,
        initialSize: resolvedInitialSize,
        layerId: initialLayerId,
        seed: baseSeed,
      }),
    ];
  });

  const previousTransitionSignatureRef = useRef(transitionSignature);

  useEffect(() => {
    if (!crossfade || transitionSignature === previousTransitionSignatureRef.current) {
      return;
    }

    previousTransitionSignatureRef.current = transitionSignature;
    const transitionIndex = transitionLayerIndexRef.current++;

    const nextLayer = createNextTransitionLayer(transitionIndex);
    setTransitionLayers((previousLayers) => [
      ...previousLayers.map((layer) => ({ ...layer, mode: "exit" as const })),
      nextLayer,
    ]);

    const timeout = window.setTimeout(
      () =>
        setTransitionLayers((previousLayers) =>
          previousLayers
            .filter((layer) => layer.mode !== "exit")
            .map((layer) => ({
              ...layer,
              mode: "steady" as const,
            })),
        ),
      reducedMotion ? 0 : EXIT_MS,
    );

    return () => window.clearTimeout(timeout);
  }, [crossfade, instanceId, reducedMotion, transitionSignature]);

  const backgroundLayers = useMemo<BubbleBackgroundLayer[]>(() => {
    if (!crossfade) {
      return layers;
    }

    return transitionLayers.map(({ layer, mode }) => ({
      ...layer,
      transitionClassName:
        mode === "enter" ? ENTER_CLASS_NAME : mode === "exit" ? EXIT_CLASS_NAME : undefined,
    }));
  }, [crossfade, layers, transitionLayers]);

  if (children === undefined) {
    return (
      <>
        {crossfade && <style>{BUBBLE_LAYER_KEYFRAMES}</style>}
        <BubbleBackground
          layers={backgroundLayers}
          className={className}
          reducedMotion={reducedMotion}
        />
      </>
    );
  }

  return (
    <div className={cn("relative isolate overflow-hidden", className)}>
      {crossfade && <style>{BUBBLE_LAYER_KEYFRAMES}</style>}
      <BubbleBackground layers={backgroundLayers} reducedMotion={reducedMotion} />
      {children}
    </div>
  );
}

"use client";

import { useMemo } from "react";

import {
  DEFAULT_BUBBLE_VIGNETTE,
  type BubbleBackgroundMotion,
} from "@/registry/radix-nova/bubble-background";
import { ConfigurableBubbleBackground } from "@/registry/radix-nova/configurable-bubble-background";
import {
  type BubbleBackgroundSceneConfig,
  type BubbleBackgroundTheme,
  type BubbleBackgroundThemeDefaults,
  type ConfigurableBubbleBackgroundProps,
} from "@/registry/radix-nova/bubble-background-helpers";

export type SidebarBubbleBackgroundTheme = BubbleBackgroundTheme & {
  key: string;
  hue: number;
};

export type SidebarBubbleBackgroundProps = ConfigurableBubbleBackgroundProps & {
  theme?: SidebarBubbleBackgroundTheme;
  /** [minPx, maxPx] pixel size range for each bubble. Defaults to [180, 360] (sidebar scale). */
  bubbleSize?: [number, number];
  seed?: number;
};

const DEFAULT_BUBBLE_COUNT = 12;

const DEFAULT_SIDEBAR_MOTION: BubbleBackgroundMotion = {
  driftMinMs: 35_000,
  driftMaxMs: 60_000,
  waypoints: 4,
  overshoot: 0.3,
};

const DEFAULT_INITIAL_SIZE = { width: 400, height: 800 };
const DEFAULT_BUBBLE_SIZE: [number, number] = [180, 360];

const SIDEBAR_THEME_DEFAULTS: BubbleBackgroundThemeDefaults = {
  key: "default",
  hue: 28,
  hueSpread: 20,
  saturation: 80,
  lightness: 70,
  opacity: 0.38,
  overlay: 0.6,
};

const SIDEBAR_SCENE_BASE: Omit<BubbleBackgroundSceneConfig, "bubbleSize"> = {
  key: "sidebar",
  vignette: DEFAULT_BUBBLE_VIGNETTE,
  initialXRange: [-0.5, 1.5],
  initialYRange: [-0.3, 1.3],
  saturationVariance: 12,
  lightnessVariance: 12,
  opacityVariance: 0.08,
  overlayTopAlphaMultiplier: 0.72,
  backdropStyle: "spread",
};

export function SidebarBubbleBackground({
  theme,
  className,
  children,
  reducedMotion: reducedMotionProp,
  bubbleCount = DEFAULT_BUBBLE_COUNT,
  blur = 50,
  motion = DEFAULT_SIDEBAR_MOTION,
  initialSize = DEFAULT_INITIAL_SIZE,
  bubbleSize = DEFAULT_BUBBLE_SIZE,
  seed,
}: SidebarBubbleBackgroundProps) {
  const [minBubbleSize, maxBubbleSize] = bubbleSize;
  const scene = useMemo<BubbleBackgroundSceneConfig>(
    () => ({ ...SIDEBAR_SCENE_BASE, bubbleSize: [minBubbleSize, maxBubbleSize] }),
    [minBubbleSize, maxBubbleSize],
  );

  return (
    <ConfigurableBubbleBackground
      theme={theme}
      themeDefaults={SIDEBAR_THEME_DEFAULTS}
      scene={scene}
      className={className}
      reducedMotion={reducedMotionProp}
      bubbleCount={bubbleCount}
      blur={blur}
      motion={motion}
      initialSize={initialSize}
      seed={seed}
      crossfade
    >
      {children}
    </ConfigurableBubbleBackground>
  );
}
